<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { errorMessage, errorCode, formatTime, mutationAttempt } from '@/features/versions/api'
import * as api from './api'
const changing=ref<api.AutomationTask>()
const route=useRoute(), data=ref<api.Workspace>(), selected=ref<api.Detail>(), error=ref(''), loading=ref(false), busy=ref(false), page=ref(1), status=ref(''), creating=ref(false), caseId=ref(''), understood=ref(false)
const createAttempt=mutationAttempt<{caseId:string;modelId:string;modelVersion:string}>(), changeAttempt=mutationAttempt<{id:string;action:string}>()
const names:Record<string,string>={DRAFT:'待排队',QUEUED:'排队中',RUNNING:'生成中',COMPLETED:'候选已生成',FAILED:'失败',CANCELLED:'已取消'}
const stages:Record<string,string>={NOT_STARTED:'尚未开始',WAITING:'等待执行',GENERATING_TEST_CANDIDATES:'生成测试候选',AWAITING_HUMAN_REVIEW:'等待人工复核',FAILED:'执行失败',CANCELLED:'已取消'}
let timer:ReturnType<typeof setTimeout>|undefined, disposed=false
async function load(){clearTimeout(timer);loading.value=true;try{data.value=await api.workspace(page.value,status.value);if(selected.value)selected.value=await api.detail(selected.value.task.id);if(!disposed&&data.value.items.some(n=>['QUEUED','RUNNING'].includes(n.status)))timer=setTimeout(load,3000)}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function show(id:string){try{error.value='';selected.value=await api.detail(id)}catch(e){error.value=errorMessage(e)}}
async function submit(){if(busy.value)return;busy.value=true;error.value='';const model=data.value?.models[0];if(!model){busy.value=false;return}const a=createAttempt.get({caseId:caseId.value,modelId:model.modelId,modelVersion:model.modelVersion},0);try{const n=await api.create(a.body.caseId,{modelId:a.body.modelId,modelVersion:a.body.modelVersion},a.key);createAttempt.reset();creating.value=false;understood.value=false;await show(n.id);await load()}catch(e){error.value=errorMessage(e);if(errorCode(e))createAttempt.reset()}finally{busy.value=false}}
async function change(n:api.AutomationTask,action:string){if(busy.value)return;busy.value=true;error.value='';changing.value=n;const a=changeAttempt.get({id:n.id,action},n.recordVersion);try{await api.transition(a.body.id,a.body.action,a.key,a.version);changeAttempt.reset();changing.value=undefined;await show(a.body.id);await load()}catch(e){error.value=errorMessage(e);if(errorCode(e)){changeAttempt.reset();changing.value=undefined;await load()}}finally{busy.value=false}}
function title(n:api.AutomationTask){return data.value?.cases.find(c=>c.taskDocumentId===n.taskDocumentId)?.title||n.taskDocumentId}
onMounted(async()=>{await load();if(typeof route.query.id==='string')await show(route.query.id)})
onUnmounted(()=>{disposed=true;clearTimeout(timer)})
</script>
<template>
  <div class="page-head between"><div><div class="eyebrow">AUTO ANNOTATION</div><h1 class="t-h1">自动标注</h1><p class="t-sm muted">管理预标注任务；候选须经人工复核、提交及裁定，不能直接成为入库结果。</p></div><button class="btn btn-primary" :disabled="busy || createAttempt.pending() || changeAttempt.pending() || !data?.cases.length" @click="creating=!creating">＋ 新建自动标注任务</button></div>
  <div class="note warn boundary">当前仅接入本地测试适配器，尚未连接真实模型。测试候选的置信度固定为 0，不代表模型预测。人工建议审核接口仍待接入。</div>
  <div v-if="error" class="note danger boundary" role="alert">{{error}} <button class="btn btn-sm" @click="load">刷新</button></div>
  <section v-if="creating || createAttempt.pending()" class="card boundary"><div class="card-head"><b>新建自动标注任务</b><button class="btn btn-sm" :disabled="busy || createAttempt.pending()" @click="creating=false">关闭</button></div><div class="card-body stack-3"><label for="auto-case">已启用预标注的案例</label><select id="auto-case" v-model="caseId" class="select" :disabled="busy || createAttempt.pending()"><option value="">请选择任务与文书</option><option v-for="c in data?.cases" :key="c.taskDocumentId" :value="c.taskDocumentId">{{c.taskName}} · {{c.title}}</option></select><p class="t-sm">模型：{{data?.models[0]?.displayName}} {{data?.models[0]?.modelVersion}}</p><label><input type="checkbox" v-model="understood" :disabled="busy || createAttempt.pending()"> 我知道这是测试适配器，仅用于验证任务和候选流程。</label><button class="btn btn-primary" :disabled="busy || !caseId || !understood" @click="submit">{{createAttempt.pending()?'沿原请求重试创建':'创建待排队任务'}}</button></div></section>
  <section class="card boundary"><div class="card-head"><b>处理流程</b><span class="badge outline">{{data?.models[0]?.displayName || '读取模型配置中'}}</span></div><div class="card-body pipe"><template v-for="(step,i) in ['校验文本与范围','生成测试候选','校验候选','等待人工复核']" :key="step"><span v-if="i" class="muted">→</span><span class="phase"><span class="badge">{{i+1}}</span>{{step}}</span></template></div></section>
  <section class="grid-2 auto-body"><div class="card"><div class="card-head between"><b>自动标注任务</b><select class="select state" aria-label="自动任务状态" v-model="status" :disabled="busy || changeAttempt.pending()" @change="page=1;load()"><option value="">全部状态</option><option v-for="(name,code) in names" :key="code" :value="code">{{name}}</option></select><button class="btn btn-sm" :disabled="loading" @click="load">刷新</button></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>任务 / 文书</th><th>模型</th><th>阶段 / 状态</th><th>候选</th><th>操作</th></tr></thead><tbody><tr v-for="n in data?.items" :key="n.id"><td><b>{{title(n)}}</b><div class="mono t-xs muted">{{n.id.slice(0,8)}} · {{formatTime(n.createdAt)}}</div></td><td class="t-xs">{{n.modelId}}<br>{{n.modelVersion}} · 测试适配器</td><td><span class="badge">{{names[n.status]}}</span><div class="t-xs muted">{{stages[n.stage]}}</div></td><td>{{n.suggestionCount}}</td><td><button class="btn btn-sm" @click="show(n.id)">详情</button><button v-if="n.status==='DRAFT'" class="btn btn-sm btn-primary" :disabled="busy || createAttempt.pending() || changeAttempt.pending()" @click="change(n,'QUEUE')">排队运行</button><button v-if="['DRAFT','QUEUED'].includes(n.status)" class="btn btn-sm" :disabled="busy || createAttempt.pending() || changeAttempt.pending()" @click="change(n,'CANCEL')">取消</button></td></tr><tr v-if="!data?.items.length"><td colspan="5" class="empty muted">{{loading?'正在读取…':'暂无自动任务；请在创建任务时启用自动预标注。'}}</td></tr></tbody></table></div><div class="card-foot between"><button class="btn btn-sm" :disabled="page<=1 || busy" @click="page--;load()">上一页</button><span>共 {{data?.total||0}} 条</span><button class="btn btn-sm" :disabled="page*20>=(data?.total||0) || busy" @click="page++;load()">下一页</button></div><button v-if="changeAttempt.pending() && !busy && changing" class="btn btn-primary" @click="change(changing,'QUEUE')">沿原请求重试操作</button></div>
  <div class="stack-5"><div class="card"><div class="card-head"><b>模型说明</b></div><div class="card-body stack-3"><div v-for="m in data?.models" :key="m.modelId" class="panel"><b>{{m.displayName}} {{m.modelVersion}}</b><p class="t-xs muted">{{m.description}}</p><p class="t-xs">能力：测试要素候选；关系识别与图生成尚未接入真实模型。</p></div></div></div><div class="card"><div class="card-head"><b>复核要求</b></div><div class="card-body"><div class="note warn">机器候选不计入 X/N，不会生成标注版本，也不能直接入库。同一候选须由各标注员独立审核；当前仅可查看，审核入口待 B 的接口接入。</div></div></div></div></section>
  <section v-if="selected" class="card boundary"><div class="card-head between"><b>任务详情 · {{selected.documentTitle}}</b><button class="btn btn-sm" @click="selected=undefined">关闭</button></div><div class="card-body stack-3"><p>{{selected.taskName}} · {{names[selected.task.status]}} · {{stages[selected.task.stage]}}</p><p v-if="selected.task.failureMessage" class="note danger">{{selected.task.failureMessage}}</p><p class="mono t-xs">{{selected.task.id}} · 模型 {{selected.task.modelId}} / {{selected.task.modelVersion}}</p><p class="mono t-xs digest">固定输入摘要：{{selected.task.inputDigest}}</p><div class="tbl-wrap"><table class="tbl"><thead><tr><th>测试候选文本</th><th>UTF-16 范围</th><th>候选类型</th><th>置信度</th><th>人工状态</th></tr></thead><tbody><tr v-for="s in selected.suggestions" :key="s.id"><td>{{s.text}}</td><td>[{{s.startOffset}}, {{s.endOffset}})</td><td>{{s.candidateLabelCode}}</td><td>{{s.confidence}}（测试固定值）</td><td>等待逐人独立复核</td></tr><tr v-if="!selected.suggestions.length"><td colspan="5" class="muted">尚未发布候选</td></tr></tbody></table></div><details><summary>模型与状态来源记录（{{selected.events.length}} 条）</summary><pre>{{JSON.stringify(selected.events,null,2)}}</pre></details><button class="btn btn-secondary" disabled>人工建议审核待接入</button></div></section>
</template>
<style scoped>.t-h1{margin:6px 0}.boundary{margin:20px 0}.auto-body{grid-template-columns:1.8fr 1fr;align-items:start}.pipe{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.phase{display:flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid var(--border);border-radius:var(--r-md)}.state{width:140px}.card-head{gap:10px;flex-wrap:wrap}.empty{padding:35px 15px;text-align:center}.tbl td{overflow-wrap:anywhere}.digest,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap}.panel{padding:12px}@media(max-width:1100px){.auto-body{grid-template-columns:1fr}}@media(max-width:650px){.page-head{flex-direction:column;align-items:flex-start;gap:15px}}</style>
